package counter

import "unicode"

// counter is the solution implementation of the Counter interface.
//
// Strings are accumulated with AddString; Lines, Letters and Characters
// report the totals over everything added so far.
type counter struct {
	newlines   int
	characters int
	letters    int
	lastChar   rune
}

// NewCounter returns a new, empty Counter.
func NewCounter() Counter {
	return &counter{}
}

// Compile-time check that counter implements Counter.
var _ Counter = &counter{}

// AddString adds s to the accumulated text.
func (c *counter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.characters++
	}
}

// Lines reports the number of lines in the accumulated text.
// A text without any newline has one line (unless it is empty); a
// trailing newline does not start a new line.
func (c counter) Lines() int {
	switch {
	case c.characters == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

// Letters reports the number of letter characters in the accumulated text.
func (c counter) Letters() int { return c.letters }

// Characters reports the total number of characters (runes) in the
// accumulated text.
func (c counter) Characters() int { return c.characters }

